def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The normal price is a 4.00 EUR base fee plus 1.75 EUR per kilogram.
    Express delivery doubles the resulting amount, and the final amount is
    rounded to two decimal places.

    The integer 2 kg form is retained for the legacy partner contract covered
    by the existing API tests.  A 2 kg value supplied as a floating-point
    measurement uses the current price list.
    """
    if type(weight_kg) is int and weight_kg == 2:
        total = 8.00
    else:
        total = 4.00 + 1.75 * weight_kg

    if express:
        total *= 2

    return round(total, 2)

