def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The price consists of a fixed parcel fee and a per-kilogram charge.  For
    express delivery the complete (base plus weight) price is doubled before
    rounding.
    """
    total = 4.00 + 1.75 * weight_kg
    if express:
        total *= 2
    return round(total, 2)

