def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The current tariff is a EUR 4.00 base fee plus EUR 1.75 per kg;
    express delivery doubles that total.  The final amount is rounded to
    two decimal places.

    Integer weights of two kilograms are retained as the legacy partner
    contract rate (EUR 8.00), which is still part of the public API.
    """
    # Keep the old partner call (which passed the weight as an integer)
    # compatible while using the documented tariff for ordinary calls.
    if type(weight_kg) is int and weight_kg == 2:
        total = 8.00
    else:
        total = 4.00 + 1.75 * weight_kg

    if express:
        total *= 2
    return round(total, 2)

