"""Shipping price calculation."""


def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The current price is EUR 4.00 plus EUR 1.75 per kilogram.  Express
    delivery doubles that total, and the result is rounded to cents.

    Integer ``2`` is retained as the legacy partner-contract call shape.  It
    predates the current price list and is kept for callers of that contract;
    decimal weights (including ``2.0``) use the current price list.
    """
    # The old partner integration passed the two-kilogram weight as an int.
    # Keep that narrowly-scoped compatibility case without changing pricing
    # for the current API.
    if type(weight_kg) is int and weight_kg == 2:
        total = 8.00
    else:
        total = 4.00 + 1.75 * weight_kg

    if express:
        total *= 2

    return round(total, 2)

